H.background();
const vb = P.vb, vr = P.vr, W = Math.max(2, P.W);
const v = H.plot2d({ xMin: -2, xMax: 14, yMin: -1, yMax: 9 });
v.grid(); v.axes();
v.line(-2, 0, 14, 0, { color: H.colors.axis, width: 2 });
v.line(-2, W, 14, W, { color: H.colors.axis, width: 2 });
v.text("far bank", 9, W + 0.5, { color: H.colors.sub, size: 12 });
v.text("near bank", -1.5, -0.5, { color: H.colors.sub, size: 12 });
const tCross = W / Math.max(0.1, vb);
const tt = (t % (tCross + 0.4));
const yb = Math.min(W, vb * tt);
const xb = vr * Math.min(tt, tCross);
v.dot(xb, yb, { r: 7, fill: H.colors.warn });
v.arrow(xb, yb, xb, yb + vb * 0.55, { color: H.colors.good, width: 2.5 });
v.arrow(xb, yb, xb + vr * 0.55, yb, { color: H.colors.accent2, width: 2.5 });
v.arrow(xb, yb, xb + vr * 0.55, yb + vb * 0.55, { color: H.colors.violet, width: 2.5 });
const vg = Math.sqrt(vb * vb + vr * vr);
const driftAng = Math.atan2(vr, vb) * 180 / Math.PI;
H.text("Relative velocity:  v_ground = v_boat + v_river", 24, 30, { color: H.colors.ink, size: 16, weight: 700 });
H.text("v_boat = " + vb.toFixed(1) + " m/s   v_river = " + vr.toFixed(1) + " m/s   |v_ground| = " + vg.toFixed(2) + " m/s", 24, 52, { color: H.colors.sub, size: 12 });
H.text("downstream drift angle = " + driftAng.toFixed(1) + " deg from straight across", 24, 74, { color: H.colors.accent, size: 12 });
H.legend([{ label: "v_boat", color: H.colors.good }, { label: "v_river", color: H.colors.accent2 }, { label: "v_ground", color: H.colors.violet }], H.W - 150, 28);
